L38:  | /** A collection of {@link FilesetOutputSymlink}s comprising the output tree of a fileset. */
L39:  | public final class FilesetOutputTree {
L40:  |
L41:  | private static final GoogleLogger logger = GoogleLogger.forEnclosingClass();
L42:  |
L43:  | public static final FilesetOutputTree EMPTY = new FilesetOutputTree(ImmutableList.of(), false);
L44:  | private static final int MAX_SYMLINK_TRAVERSALS = 256;
L45:  |
L46:  | public static FilesetOutputTree create(ImmutableList<FilesetOutputSymlink> symlinks) {
L47:  | return symlinks.isEmpty()
L48:  | ? EMPTY
L49:  | : new FilesetOutputTree(
L50:  | symlinks, symlinks.stream().anyMatch(FilesetOutputTree::isRelativeSymlink));
L51:  | }
L52:  |
L53:  | private final ImmutableList<FilesetOutputSymlink> symlinks;
L54:  | private final boolean hasRelativeSymlinks;
L55:  |
L56:  | private FilesetOutputTree(
L57:  | ImmutableList<FilesetOutputSymlink> symlinks, boolean hasRelativeSymlinks) {
L58:  | this.symlinks = checkNotNull(symlinks);
L59:  | this.hasRelativeSymlinks = hasRelativeSymlinks;
L60:  | }
L61:  |
L62:  | /** Receiver for the symlinks in a fileset's output tree. */
L63:  | @FunctionalInterface
L64:  | public interface Visitor<E1 extends Exception, E2 extends Exception> {
L65:  |
L66:  | /**
L67:  | * Called for each symlink in the fileset's output tree.
L68:  | *
L69:  | * @param name path of the symlink relative to the fileset's root; equivalent to {@link
L70:  | * FilesetOutputSymlink#getName}
L71:  | * @param target symlink target; either an absolute path if the symlink points to a source file
L72:  | * or an execroot-relative path if the symlink points to an output
L73:  | * @param metadata a {@link FileArtifactValue} representing the target's metadata if available,
L74:  | * or {@code null}
L75:  | */
L76:  | void acceptSymlink(PathFragment name, PathFragment target, @Nullable FileArtifactValue metadata)
L77:  | throws E1, E2;
L78:  | }
L79:  |
L80:  | /**
L81:  | * Visits the symlinks in this fileset tree, handling relative symlinks according to the given
L82:  | * {@link RelativeSymlinkBehavior}.
L83:  | */
L84:  | public <E1 extends Exception, E2 extends Exception> void visitSymlinks(
L85:  | RelativeSymlinkBehavior relSymlinkBehavior, Visitor<E1, E2> visitor)
L86:  | throws ForbiddenRelativeSymlinkException, E1, E2 {
L87:  | var relSymlinkBehaviorWithoutError =
L88:  | switch (relSymlinkBehavior) {
L89:  | case RESOLVE_FULLY -> RelativeSymlinkBehaviorWithoutError.RESOLVE_FULLY;
L90:  | case RESOLVE -> RelativeSymlinkBehaviorWithoutError.RESOLVE;
L91:  | case IGNORE -> RelativeSymlinkBehaviorWithoutError.IGNORE;
L92:  | case ERROR -> {
L93:  | if (hasRelativeSymlinks) {
L94:  | FilesetOutputSymlink relativeLink =
L95:  | symlinks.stream().filter(FilesetOutputTree::isRelativeSymlink).findFirst().get();
L96:  | throw new ForbiddenRelativeSymlinkException(relativeLink);
L97:  | }
L98:  | yield RelativeSymlinkBehaviorWithoutError.IGNORE;
L99:  | }
L100:  | };
L101:  | visitSymlinks(relSymlinkBehaviorWithoutError, visitor);
L102:  | }
L103:  |
L104:  | /**
L105:  | * Visits the symlinks in this fileset tree, handling relative symlinks according to the given
L106:  | * {@link RelativeSymlinkBehaviorWithoutError}.
L107:  | */
L108:  | public <E1 extends Exception, E2 extends Exception> void visitSymlinks(
L109:  | RelativeSymlinkBehaviorWithoutError relSymlinkBehavior, Visitor<E1, E2> visitor)
L110:  | throws E1, E2 {
L111:  | // Fast path: if we don't need to resolve relative symlinks (either because there are none or
L112:  | // because we are ignoring them), perform a single-pass visitation. This is expected to be the
L113:  | // common case.
L114:  | if (!hasRelativeSymlinks || relSymlinkBehavior == RelativeSymlinkBehaviorWithoutError.IGNORE) {
L115:  | for (FilesetOutputSymlink symlink : symlinks) {
L116:  | if (!isRelativeSymlink(symlink)) {
L117:  | visitor.acceptSymlink(
L118:  | symlink.getName(),
L119:  | symlink.getTargetPath(),
L120:  | symlink.getMetadata() instanceof FileArtifactValue metadata ? metadata : null);
L121:  | }
L122:  | }
L123:  | return;
L124:  | }
L125:  |
L126:  | // Symlink name to resolved target path. Relative target paths are relative to the exec root.
L127:  | Map<PathFragment, String> resolvedLinks = new LinkedHashMap<>();
L128:  | // Symlink name to relative target path.
L129:  | Map<PathFragment, String> relativeLinks = new HashMap<>();
L130:  | // Resolved target path to metadata.
L131:  | Map<String, FileArtifactValue> artifactValues = new HashMap<>();
L132:  |
L133:  | for (FilesetOutputSymlink outputSymlink : symlinks) {
L134:  | PathFragment name = outputSymlink.getName();
L135:  | String targetPath = outputSymlink.getTargetPath().getPathString();
L136:  | var map = isRelativeSymlink(outputSymlink) ? relativeLinks : resolvedLinks;
L137:  |
L138:  | // Symlinks are already deduplicated by name in SkyframeFilesetManifestAction.
L139:  | checkState(map.put(name, targetPath) == null, "Duplicate fileset entry at %s", name);
L140:  |
L141:  | if (outputSymlink.getMetadata() instanceof FileArtifactValue metadata) {
L142:  | artifactValues.put(targetPath, metadata);
L143:  | }
L144:  | }
L145:  |
L146:  | if (relSymlinkBehavior == RelativeSymlinkBehaviorWithoutError.RESOLVE_FULLY) {
L147:  | fullyResolveRelativeSymlinks(resolvedLinks, relativeLinks);
L148:  | } else {
L149:  | resolveRelativeSymlinks(resolvedLinks, relativeLinks);
L150:  | }
L151:  |
L152:  | for (var entry : resolvedLinks.entrySet()) {
L153:  | PathFragment name = entry.getKey();
L154:  | String target = entry.getValue();
L155:  | FileArtifactValue metadata = artifactValues.get(target);
L156:  | visitor.acceptSymlink(name, PathFragment.create(target), metadata);
L157:  | }
L158:  | }
