L160:  | public ImmutableList<FilesetOutputSymlink> symlinks() {
L161:  | return symlinks;
L162:  | }
L163:  |
L164:  | public int size() {
L165:  | return symlinks.size();
L166:  | }
L167:  |
L168:  | public boolean isEmpty() {
L169:  | return symlinks.isEmpty();
L170:  | }
L171:  |
L172:  | @Override
L173:  | public int hashCode() {
L174:  | return symlinks.hashCode();
L175:  | }
L176:  |
L177:  | @Override
L178:  | public boolean equals(Object o) {
L179:  | if (this == o) {
L180:  | return true;
L181:  | }
L182:  | if (!(o instanceof FilesetOutputTree that)) {
L183:  | return false;
L184:  | }
L185:  | return symlinks.equals(that.symlinks);
L186:  | }
L187:  |
L188:  | @Override
L189:  | public String toString() {
L190:  | return MoreObjects.toStringHelper(this)
L191:  | .add("symlinks", symlinks)
L192:  | .add("hasRelativeSymlinks", hasRelativeSymlinks)
L193:  | .toString();
L194:  | }
