L196:  | /** Mode that determines how to handle relative target paths. */
L197:  | public enum RelativeSymlinkBehavior {
L198:  | /** Ignore any relative target paths. */
L199:  | IGNORE,
L200:  | /** Give an error if a relative target path is encountered. */
L201:  | ERROR,
L202:  | /** Resolve relative target paths that (transitively) point to another file in the fileset. */
L203:  | RESOLVE,
L204:  | /**
L205:  | * Fully resolve all relative paths, even those pointing to internal directories. Then do a
L206:  | * virtual filesystem traversal to find all paths to all files in the fileset.
L207:  | */
L208:  | RESOLVE_FULLY
L209:  | }
L210:  |
L211:  | /**
L212:  | * Shadow of {@link RelativeSymlinkBehavior} without the {@link RelativeSymlinkBehavior#ERROR}
L213:  | * value for callers who know there won't be an error thrown when constructing the manifest.
L214:  | */
L215:  | public enum RelativeSymlinkBehaviorWithoutError {
L216:  | /** Ignore any relative target paths. */
L217:  | IGNORE,
L218:  | /** Resolve all relative target paths. */
L219:  | RESOLVE,
L220:  | /** Fully resolve all relative paths, even those pointing to internal directories. */
L221:  | RESOLVE_FULLY
L222:  | }
L223:  |
L224:  | private static boolean isRelativeSymlink(FilesetOutputSymlink symlink) {
L225:  | return !symlink.getTargetPath().isAbsolute() && !symlink.isRelativeToExecRoot();
L226:  | }
L227:  |
L228:  | /** Fully resolves relative symlinks, including internal directory symlinks. */
L229:  | private static void fullyResolveRelativeSymlinks(
L230:  | Map<PathFragment, String> resolvedLinks, Map<PathFragment, String> relativeLinks) {
L231:  | try {
L232:  | // Construct an in-memory Filesystem containing all the non-relative-symlink entries in the
L233:  | // Fileset. Treat these as regular files in the filesystem whose contents are the "real"
L234:  | // symlink pointing out of the Fileset. For relative symlinks, we encode these as symlinks in
L235:  | // the in-memory Filesystem. This allows us to then crawl the filesystem for files. Any
L236:  | // readable file is a valid part of the FilesetManifest. Dangling internal links or symlink
L237:  | // cycles will be discovered by the in-memory filesystem.
L238:  | // (Choice of digest function is irrelevant).
L239:  | InMemoryFileSystem fs = new InMemoryFileSystem(DigestHashFunction.SHA256);
L240:  | Path root = fs.getPath("/");
L241:  | for (Map.Entry<PathFragment, String> e : resolvedLinks.entrySet()) {
L242:  | PathFragment location = e.getKey();
L243:  | Path locationPath = root.getRelative(location);
L244:  | locationPath.getParentDirectory().createDirectoryAndParents();
L245:  | FileSystemUtils.writeContentAsLatin1(locationPath, e.getValue());
L246:  | }
L247:  | for (Map.Entry<PathFragment, String> e : relativeLinks.entrySet()) {
L248:  | PathFragment location = e.getKey();
L249:  | Path locationPath = fs.getPath("/").getRelative(location);
L250:  | PathFragment value = PathFragment.create(checkNotNull(e.getValue(), e));
L251:  |
L252:  | locationPath.getParentDirectory().createDirectoryAndParents();
L253:  | locationPath.createSymbolicLink(value);
L254:  | }
L255:  |
L256:  | addSymlinks(root, resolvedLinks);
L257:  | } catch (IOException e) {
L258:  | throw new IllegalStateException("InMemoryFileSystem can't throw", e);
L259:  | }
L260:  | }
L261:  |
L262:  | private static void addSymlinks(Path root, Map<PathFragment, String> resolvedLinks)
L263:  | throws IOException {
L264:  | for (Path path : root.getDirectoryEntries()) {
L265:  | try {
L266:  | if (path.isDirectory()) {
L267:  | addSymlinks(path, resolvedLinks);
L268:  | } else {
L269:  | String contents = new String(FileSystemUtils.readContentAsLatin1(path));
L270:  | resolvedLinks.put(path.asFragment().toRelative(), contents);
L271:  | }
L272:  | } catch (IOException e) {
L273:  | logger.atWarning().log("Symlink %s is dangling or cyclic: %s", path, e.getMessage());
L274:  | }
L275:  | }
L276:  | }
L277:  |
L278:  | /** Resolves relative symlinks and puts them in the {@code resolvedLinks} map. */
L279:  | private static void resolveRelativeSymlinks(
L280:  | Map<PathFragment, String> resolvedLinks, Map<PathFragment, String> relativeLinks) {
L281:  | for (Map.Entry<PathFragment, String> e : relativeLinks.entrySet()) {
L282:  | PathFragment location = e.getKey();
L283:  | String actual = e.getValue();
L284:  | PathFragment actualLocation = location;
L285:  |
L286:  | // Recursively resolve relative symlinks.
L287:  | LinkedHashSet<String> seen = new LinkedHashSet<>();
L288:  | int traversals = 0;
L289:  | do {
L290:  | actualLocation = actualLocation.getParentDirectory().getRelative(actual);
L291:  | actual = relativeLinks.get(actualLocation);
L292:  | } while (++traversals <= MAX_SYMLINK_TRAVERSALS && actual != null && seen.add(actual));
L293:  |
L294:  | if (traversals >= MAX_SYMLINK_TRAVERSALS) {
L295:  | logger.atWarning().log(
L296:  | "Symlink %s is part of a chain of length at least %d"
L297:  | + " which exceeds Blaze's maximum allowable symlink chain length",
L298:  | location, traversals);
L299:  | } else if (actual != null) {
L300:  | // TODO(b/113128395): throw here.
L301:  | logger.atWarning().log("Symlink %s forms a symlink cycle: %s", location, seen);
L302:  | } else {
L303:  | String resolvedTarget = resolvedLinks.get(actualLocation);
L304:  | if (resolvedTarget == null) {
L305:  | // We've found a relative symlink that points out of the fileset. We should really
L306:  | // always throw here, but current behavior is that we tolerate such symlinks when they
L307:  | // occur in runfiles, which is the only time this code is hit.
L308:  | // TODO(b/113128395): throw here.
L309:  | logger.atWarning().log(
L310:  | "Symlink %s (transitively) points to %s that is not in this fileset (or was"
L311:  | + " pruned because of a cycle)",
L312:  | location, actualLocation);
L313:  | } else {
L314:  | // We have successfully resolved the symlink.
L315:  | resolvedLinks.put(location, resolvedTarget);
L316:  | }
L317:  | }
L318:  | }
L319:  | }
