L321:  | /** Exception indicating that a relative symlink was encountered but not permitted. */
L322:  | public static final class ForbiddenRelativeSymlinkException
L323:  | extends ForbiddenActionInputException {
L324:  | private ForbiddenRelativeSymlinkException(FilesetOutputSymlink relativeLink) {
L325:  | super(
L326:  | "Fileset symlink %s -> %s is not absolute"
L327:  | .formatted(relativeLink.getName(), relativeLink.getTargetPath()));
L328:  | }
L329:  | }
